// Checks against PortExport/ (generated by running the web game's own code): the hand-copied config, the collision
// triangles of the three maps, and the 16 Mover trajectories replayed through the C# Mover on the C# port of the
// web's collision world (three.js Octree). The same trajectories on Unity physics: Skygrind.Game.Tests.
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using NUnit.Framework;
using UnityEngine;
using static Skygrind.Core.PortData;

namespace Skygrind.Core.Tests
{
    public class PortExportTests
    {
        /// <summary>The replay order asked for: walk, jump, slide, dash, wall ride, then the swings and the ramp runs.</summary>
        public static readonly string[] TrajectoryOrder =
        {
            "walk", "walk_diagonal", "run_jump_double", "short_hop", "bunny_hop", "slide", "slide_jump", "dash", "dash_jump",
            "slam_boost", "wall_ride", "wall_jump", "swing", "swing_from_ground", "ramp_walk_up", "ramp_slide_down",
        };

        [Test, Description("every MovementConfig value (hand-copied from config.js) equals config.json")]
        public void Config_MatchesConfigJson()
        {
            var differences = new List<string>();
            LoadConfig(Obj(Port.Json("config.json")), differences);
            Assert.IsEmpty(differences, string.Join("\n", differences));
        }

        [Test, Description("TrainingMap (hand-copied) has the same boxes, pads and spawn as maps/training.json")]
        public void TrainingMap_MatchesMapFile()
        {
            var file = Obj(Port.Json("maps/training.json"));
            var boxes = Arr(Obj(file["collision"])["boxes"]).ConvertAll(Box);
            ArenaMap ours = TrainingMap.Build();
            Assert.AreEqual(boxes.Count, ours.boxes.Count, "box count");
            for (int i = 0; i < boxes.Count; i++)
            {
                Assert.AreEqual(boxes[i].min, ours.boxes[i].min, $"box {i} min");
                Assert.AreEqual(boxes[i].max, ours.boxes[i].max, $"box {i} max");
            }
            var pads = Arr(file["pads"]).ConvertAll(Obj);
            for (int i = 0; i < pads.Count; i++) Assert.AreEqual(new Vec3(Num(pads[i]["x"]), Num(pads[i]["y"]), Num(pads[i]["z"])), ours.pads[i].pos, $"pad {i}");
            Assert.AreEqual(0, Arr(Obj(file["collision"])["wedges"]).Count, "the web training map has no wedges (the spike's ramps are additions)");
        }

        static IEnumerable<string> Maps() => new[] { "spire", "training", "survival" };

        [TestCaseSource(nameof(Maps)), Description("the C# Octree built from the map's boxes and wedges holds exactly the stored triangles, in the stored order, and drops exactly the listed ones")]
        public void MapOctree_MatchesStoredTriangles(string name)
        {
            var map = Obj(Port.Json($"maps/{name}.json"));
            var collision = Obj(map["collision"]);
            ThreeOctree octree = BuildMapOctree(map);
            var stored = Arr(Obj(collision["triangles"])["flat"]).ConvertAll(Num);
            List<ThreeOctree.Triangle> ours = octree.StoredTriangles();
            Assert.AreEqual(stored.Count / 9, ours.Count, "triangle count");
            for (int i = 0; i < ours.Count; i++)
            {
                ThreeOctree.Triangle t = ours[i];
                double[] got = { t.a.x, t.a.y, t.a.z, t.b.x, t.b.y, t.b.z, t.c.x, t.c.y, t.c.z };
                for (int k = 0; k < 9; k++)
                {
                    if (BitConverter.DoubleToInt64Bits(got[k]) != BitConverter.DoubleToInt64Bits(stored[i * 9 + k]))
                        Assert.Fail($"triangle {i} component {k}: stored {Describe(stored[i * 9 + k])}, C# {Describe(got[k])}");
                }
            }
            var dropped = Obj(collision["droppedByOctree"]);
            Assert.AreEqual((int)Num(dropped["count"]), octree.DroppedTriangles().Count, "dropped count");
            TestContext.WriteLine($"{name}: {ours.Count} triangles identical in order and bits; {octree.DroppedTriangles().Count} dropped, as stored");
        }

        static IEnumerable<string> Trajectories() => TrajectoryOrder;

        /// <summary>The C# version of the collider a trajectory ran against.</summary>
        public static ThreeOctree ReferenceWorld(Trajectory t)
        {
            if (t.SceneKind == "boxes") return ThreeGeometry.BuildOctree(Arr(t.scene["boxes"]).ConvertAll(Box), null);
            return BuildMapOctree(Obj(Port.Json($"maps/{t.scene["map"]}.json")));
        }

        public static Trajectory Load(string name) => Trajectory.Load(Path.Combine(Port.Root, "trajectories", name + ".json"));

        [TestCaseSource(nameof(Trajectories)), Description("recorded inputs -> C# Mover on the C# three.js Octree: position, velocity, state and events equal the recording at every step, bit for bit")]
        public void Trajectory_ReplaysExactly_OnReferenceWorld(string name)
        {
            Trajectory t = Load(name);
            ReplayReport r = TrajectoryReplay.Run(t, ReferenceWorld(t), Port.Config);
            string line = Summary(r);
            TestContext.WriteLine(line);
            WriteReport("replay-reference.md", name, line);
            Assert.IsTrue(r.Exact, line);
        }

        /// <summary>NIGHT9 U3-07: the 6 trial routes (port-export-p18 trialRoutes.mjs), on their maps with the pads.</summary>
        public static readonly string[] TrialRoutes =
        {
            "trial_slideLine", "trial_gapRunner", "trial_wallRider", "trial_slamDeck", "trial_targetRun", "trial_skybridge",
        };

        static IEnumerable<string> Trials() => TrialRoutes;

        [TestCaseSource(nameof(Trials)), Description("a trial's par route: recorded inputs -> C# Mover on the map's collider (the core at the trial's preset), arena.js checkPads after every step; bit for bit at every step (Skygrind.Core Golden.Replay, as the Player's -skygrindGolden)")]
        public void Trajectory_ReplaysExactly_TrialRoute(string name)
        {
            ReplayReport r = Golden.Replay(OracleGoldenTests.Data, name);
            string line = Summary(r);
            TestContext.WriteLine(line);
            Assert.IsTrue(r.Exact, line);
        }

        public static string Summary(ReplayReport r) =>
            r.Exact
                ? $"{r.name}: PASS, {r.steps} steps identical (position, velocity, state, events, pips, gravity multiplier, rope)"
                : string.Format(CultureInfo.InvariantCulture,
                    "{0}: FAIL at step {1} of {2}: {3} | size at first divergence {4:G3}; max over the run: position {5:G3} m, velocity {6:G3} m/s; steps with a state difference {7}, with an event difference {8}",
                    r.name, r.firstDivergentStep, r.steps, r.firstDifference, r.divergenceAtFirst, r.maxPositionDiff, r.maxVelocityDiff, r.stepsWithStateDiff, r.stepsWithEventDiff);

        /// <summary>Appends a row to Logs/&lt;file&gt; (one line per trajectory, replaced on rerun).</summary>
        public static void WriteReport(string file, string name, string line)
        {
            string path = Path.GetFullPath(Path.Combine(Application.dataPath, "..", "Logs", file));
            Directory.CreateDirectory(Path.GetDirectoryName(path));
            var lines = File.Exists(path) ? File.ReadAllLines(path).Where(l => !l.StartsWith(name + ":")).ToList() : new List<string>();
            lines.Add(line);
            lines.Sort((a, b) => Array.IndexOf(TrajectoryOrder, a.Split(':')[0]).CompareTo(Array.IndexOf(TrajectoryOrder, b.Split(':')[0])));
            File.WriteAllLines(path, lines, Encoding.UTF8);
        }
    }
}
